import dlansy = require( './index' );


// TESTS //

// The function returns a number...
{
	const A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	dlansy( 'row-major', 'M', 'upper', 2, A, 2 ); // $ExpectType number
	dlansy( 'column-major', '1', 'lower', 2, A, 2 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	dlansy( 5, 'M', 'upper', 2, A, 2 ); // $ExpectError
	dlansy( true, 'M', 'upper', 2, A, 2 ); // $ExpectError
	dlansy( false, 'M', 'upper', 2, A, 2 ); // $ExpectError
	dlansy( null, 'M', 'upper', 2, A, 2 ); // $ExpectError
	dlansy( void 0, 'M', 'upper', 2, A, 2 ); // $ExpectError
	dlansy( [], 'M', 'upper', 2, A, 2 ); // $ExpectError
	dlansy( {}, 'M', 'upper', 2, A, 2 ); // $ExpectError
	dlansy( ( x: number ): number => x, 'M', 'upper', 2, A, 2 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a string...
{
	const A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	dlansy( 'row-major', 5, 'upper', 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', true, 'upper', 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', false, 'upper', 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', null, 'upper', 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', void 0, 'upper', 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', [], 'upper', 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', {}, 'upper', 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', ( x: number ): number => x, 'upper', 2, A, 2 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a string...
{
	const A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	dlansy( 'row-major', 'M', 5, 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', true, 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', false, 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', null, 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', void 0, 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', [], 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', {}, 2, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', ( x: number ): number => x, 2, A, 2 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	dlansy( 'row-major', 'M', 'upper', '5', A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', true, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', false, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', null, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', void 0, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', [], A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', {}, A, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', ( x: number ): number => x, A, 2 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a Float64Array...
{
	dlansy( 'row-major', 'M', 'upper', 2, '5', 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, 5, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, true, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, false, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, null, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, void 0, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, [], 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, {}, 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, ( x: number ): number => x, 2 ); // $ExpectError
}

// The compiler throws an error if the function is provided a sixth argument which is not a number...
{
	const A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	dlansy( 'row-major', 'M', 'upper', 2, A, '5' ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, A, true ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, A, false ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, A, null ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, A, void 0 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, A, [] ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, A, {} ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, A, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	dlansy(); // $ExpectError
	dlansy( 'row-major' ); // $ExpectError
	dlansy( 'row-major', 'M' ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper' ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2 ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, A ); // $ExpectError
	dlansy( 'row-major', 'M', 'upper', 2, A, 2, 10 ); // $ExpectError
}

// Attached to the main export is an `ndarray` method which returns a number...
{
	const A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	dlansy.ndarray( 'M', 'upper', 2, A, 2, 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a string...
{
	const A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	dlansy.ndarray( 5, 'upper', 2, A, 2, 1, 0 ); // $ExpectError
	dlansy.ndarray( true, 'upper', 2, A, 2, 1, 0 ); // $ExpectError
	dlansy.ndarray( false, 'upper', 2, A, 2, 1, 0 ); // $ExpectError
	dlansy.ndarray( null, 'upper', 2, A, 2, 1, 0 ); // $ExpectError
	dlansy.ndarray( void 0, 'upper', 2, A, 2, 1, 0 ); // $ExpectError
	dlansy.ndarray( [], 'upper', 2, A, 2, 1, 0 ); // $ExpectError
	dlansy.ndarray( {}, 'upper', 2, A, 2, 1, 0 ); // $ExpectError
	dlansy.ndarray( ( x: number ): number => x, 'upper', 2, A, 2, 1, 0 ); // $ExpectError
}

