// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	dlansy.ndarray(); // $ExpectError
	dlansy.ndarray( 'M' ); // $ExpectError
	dlansy.ndarray( 'M', 'upper' ); // $ExpectError
	dlansy.ndarray( 'M', 'upper', 2 ); // $ExpectError
	dlansy.ndarray( 'M', 'upper', 2, A ); // $ExpectError
	dlansy.ndarray( 'M', 'upper', 2, A, 2 ); // $ExpectError
	dlansy.ndarray( 'M', 'upper', 2, A, 2, 1 ); // $ExpectError
	dlansy.ndarray( 'M', 'upper', 2, A, 2, 1, 0, 10 ); // $ExpectError
}
